def _validate_request(auth_token):
    """Validate the parts of a request required before processing it.

    Authentication is deliberately performed before the request data is handed
    to ``process`` so that unauthenticated requests cannot trigger processing.
    """
    if not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")


def handle_request(data, auth_token):
    """Authenticate and process an incoming API request."""
    _validate_request(auth_token)
    return process(data)

